insert into public.site_settings (id, owner_name, initials, brand_name, site_url, contact_email, phone, whatsapp, location, role, tagline, hero_intro, about, availability, seo_title, seo_description, og_image_url, avatar_url, accent_color, default_theme, socials, features, cv_url, is_example) values
  (1, 'Patrick Melaga', 'PM', 'Patrick Melaga', 'http://localhost:3000', 'contact@example.com', '+237 600 000 000', '237600000000', '{"fr":"Yaoundé, Cameroun","en":"Yaoundé, Cameroon"}'::jsonb, '{"fr":"Administrateur Réseaux & Systèmes · Développeur Full-Stack · Designer","en":"Network & Systems Administrator · Full-Stack Developer · Designer"}'::jsonb, '{"fr":"Une ingénierie rigoureuse, un design irréprochable.","en":"Rigorous engineering, impeccable design."}'::jsonb, '{"fr":"Je conçois des réseaux fiables, j''administre des serveurs qui tiennent la charge et je construis des applications web aussi solides que soignées.","en":"I design reliable networks, run servers that hold under load and build web applications that are as solid as they are polished."}'::jsonb, '{"fr":"Diplômé de l''IAI Cameroun (2023-2026), je me situe à la jonction de l''infrastructure et du produit : je sais câbler une salle serveur, segmenter un réseau, automatiser un déploiement Linux, puis concevoir l''interface qui rend tout cela utilisable. Mon parcours m''a mené du DTS à la licence professionnelle en Systèmes et Réseaux, puis au diplôme d''ingénieur des travaux informatiques, option Systèmes et Réseaux.","en":"A graduate of IAI Cameroon (2023-2026), I work where infrastructure meets product: I can wire a server room, segment a network, automate a Linux deployment, then design the interface that makes it all usable. My path took me from the DTS to a professional bachelor''s degree in Systems and Networks, then to the computer engineering technologist degree, Systems and Networks track."}'::jsonb, '{"fr":"Disponible pour un emploi, un stage ou une mission freelance.","en":"Available for a job, an internship or a freelance project."}'::jsonb, '{"fr":"Administrateur réseaux & systèmes, développeur full-stack et designer","en":"Network & systems administrator, full-stack developer and designer"}'::jsonb, '{"fr":"Portfolio : conception et sécurisation de réseaux, administration de serveurs Linux/Windows, développement web full-stack et design. Basé au Cameroun, disponible à distance.","en":"Portfolio: network design and security, Linux/Windows server administration, full-stack web development and design. Based in Cameroon, available remotely."}'::jsonb, null, null, '#FF5A1F', 'system', '{"github":"","linkedin":""}'::jsonb, '{"blog":true,"comments":true,"newsletter":true,"quotes":true,"analytics":true}'::jsonb, '{}'::jsonb, true)
